import { describe, expect, test } from "vitest";
import {
  GENERATED_FOR_OTHER_VERSION,
  refuseCodeOfOtherVersion,
} from "./generator-version-check.js";
import { SERVER_RUNTIME_VERSION } from "./version.js";

// The boot check's first step: code generated by another version never runs against this runtime.

const INSTALLED = "1.4.2";

function generatedBy(generatorVersion: string) {
  return { id: "tasks", generatorVersion };
}

describe("the boot check of the generator's version", () => {
  test("refuses a boot for code generated by another major.minor, naming both versions and the fix", () => {
    expect(() => refuseCodeOfOtherVersion(generatedBy("1.3.0"), INSTALLED)).toThrow(
      `${GENERATED_FOR_OTHER_VERSION}: The \`tasks\` boundary was generated by seampact \`1.3.0\`; the installed runtime is \`${INSTALLED}\`; fix: run \`seampact generate\` again with the generator at \`${INSTALLED}\`, or install the runtime at \`1.3.0\` or a later patch of it.`,
    );
  });

  test("refuses a boot for code generated by a later patch than the runtime", () => {
    expect(() => refuseCodeOfOtherVersion(generatedBy("1.4.3"), INSTALLED)).toThrow(
      GENERATED_FOR_OTHER_VERSION,
    );
  });

  test("refuses a prerelease it was not built as", () => {
    expect(() => refuseCodeOfOtherVersion(generatedBy("1.4.2-rc.1"), INSTALLED)).toThrow(
      GENERATED_FOR_OTHER_VERSION,
    );
  });

  test("serves code from a generator at its patch or an earlier one", () => {
    expect(() => refuseCodeOfOtherVersion(generatedBy("1.4.2"), INSTALLED)).not.toThrow();
    expect(() => refuseCodeOfOtherVersion(generatedBy("1.4.0"), INSTALLED)).not.toThrow();
  });

  test("checks against this runtime's own version by default", () => {
    expect(() => refuseCodeOfOtherVersion(generatedBy(SERVER_RUNTIME_VERSION))).not.toThrow();
    expect(() => refuseCodeOfOtherVersion(generatedBy("999.0.0"))).toThrow(
      `the installed runtime is \`${SERVER_RUNTIME_VERSION}\``,
    );
  });
});
